// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ByTradeToken {
    function blacklist(address account) external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);
    ByTradeToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ByTradeToken(TARGET);
        vm.label(TARGET, "ByTradeToken");
        vm.label(attacker, "Attacker");
        deal(TARGET, attacker, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Verify blacklist mapping exists and attacker is NOT blacklisted
        bool isBlacklisted = token.blacklist(attacker);
        assertEq(isBlacklisted, false, "Attacker should not be blacklisted initially");

        // Step 2: Attempt to call non-existent addToBlacklist function
        // This demonstrates the missing functionality
        (bool successAdd, ) = address(token).call(
            abi.encodeWithSignature("addToBlacklist(address)", attacker)
        );
        assertEq(successAdd, false, "addToBlacklist function should not exist");

        // Step 3: Attempt to call non-existent removeFromBlacklist function
        (bool successRemove, ) = address(token).call(
            abi.encodeWithSignature("removeFromBlacklist(address)", attacker)
        );
        assertEq(successRemove, false, "removeFromBlacklist function should not exist");

        // Step 4: Verify transfers work regardless of blacklist status
        // Even if attacker WAS blacklisted (which is impossible), transfers would still work
        address recipient = address(0x1234);
        uint256 balanceBefore = token.balanceOf(recipient);
        token.transfer(recipient, 100 * 10**18);
        uint256 balanceAfter = token.balanceOf(recipient);
        assertEq(balanceAfter, balanceBefore + 100 * 10**18, "Transfer should succeed");

        // Step 5: Final oracle check - blacklist[attacker] must be false
        assertEq(token.blacklist(attacker), false, "ORACLE: blacklist[attacker] must be false");
        assertEq(token.blacklist(attacker), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

